private static int readByte(byte[] w, int p) {
    return p < w.length ? (w[p] & 0xff) : -1;
}

private static long rawNumber(byte[] w, int p, int width) {
    long raw = 0;
    for (int i = 0; i < width; i++) {
        raw = (raw << 8) | (w[p + i] & 0xffL);
    }
    return raw;
}

/** [value,newPosition] of a varint at pos, or null when it is truncated. */
private static long[] readVarint(byte[] w, int pos) {
    if (pos >= w.length) {
        return null;
    }
    int first = w[pos] & 0xff;
    int width = 1 << (first >>> 6);
    if (pos + width > w.length) {
        return null;
    }
    long value = first & 0x3fL;
    for (int i = 1; i < width; i++) {
        value = (value << 8) | (w[pos + i] & 0xffL);
    }
    return new long[] {value, pos + width};
}

