private boolean processEnvelope(int event, int index, int headerOffset, Envelope env, List<Long> auth,
        List<Object> packets, ByteArrayOutputStream acceptedBytes) {
    int level = env.level;
    long expected = largest[level] < 0 ? 0L : largest[level] + 1;
    long pn = Canonical.reconstruct(env.rawPn, expected, env.pnWidth);
    Long annotation = (auth != null && index < auth.size()) ? auth.get(index) : null;
    String status;
    Long epoch = null;
    byte[] canonical = null;
    if (closed) {
        status = "CLOSED";
    } else {
        Integer seq = localCidIndex.get(Main.hex(env.dcid));
        if (seq == null || retiredLocal.contains(seq)) {
            status = "DROP_CID";
        } else {
            env.destSeq = seq;
            if (!activeKeys[level]) {
                status = "NO_KEY";
            } else if (pn > MAX62) {
                status = "PN_RANGE";
            } else {
                boolean authentic;
                if (level == A) {
                    authentic = false;
                    if (annotation != null) {
                        long generation = annotation;
                        boolean window = generation == currentEpoch
                                || (generation == currentEpoch + 1 && currentEpoch + 1 <= MAX62)
                                || (currentEpoch > 0 && generation == currentEpoch - 1);
                        authentic = window && (generation & 1L) == (long) env.phase;
                        if (authentic) {
                            epoch = generation;
                        }
                    }
                } else {
                    authentic = annotation != null && annotation == 0L;
                }
                if (!authentic) {
                    status = "AUTH";
                } else if (seen[level].contains(pn)) {
                    status = "DUPLICATE";
                } else if (level == A && !epochOrderOk(epoch, pn)) {
                    status = "KEY_UPDATE_ERROR";
                    close(event, index, 0, "KEY_UPDATE_ERROR");
                } else {
                    Outcome outcome = auditPacket(event, index, env, pn, expected);
                    status = outcome.status;
                    canonical = outcome.canonical;
                    if (canonical != null) {
                        accept(level, pn, epoch);
                        acceptedBytes.write(canonical, 0, canonical.length);
                    }
                }
            }
        }
    }
    packets.add(row(event, index, headerOffset, LEVEL[level], pn, epoch, status,
            canonical == null ? null : hash(canonical)));
    return canonical != null;
}

/** Outcome of one audited packet: its status and, when accepted, its canonical envelope. */
private static final class Outcome {
    final String status;
    final byte[] canonical;

    Outcome(String status, byte[] canonical) {
        this.status = status;
        this.canonical = canonical;
    }
}

/**
 * Audits every frame of one packet inside a transaction. Accepted packets commit their effects
 * and yield the canonical envelope; failures roll the packet back and close the connection.
 */
private Outcome auditPacket(int event, int index, Envelope env, long pn, long expected) {
    beginTransaction();
    try {
        Frames frames = auditFrames(env);
        byte[] canonical = Canonical.envelope(env.level, env.dcid, env.scid, env.token, env.phase, pn, expected,
                frames.payload);
        commitTransaction();
        if (frames.close) {
            close(event, index, frames.closeOffset, "PEER_CLOSE");
            return new Outcome("PEER_CLOSE", canonical);
        }
        return new Outcome("OK", canonical);
    } catch (AuditException failure) {
        rollbackTransaction();
        close(event, index, failure.offset, failure.code);
        return new Outcome(failure.code, null);
    } catch (RuntimeException failure) {
        rollbackTransaction();
        close(event, index, 0, "FRAME_ENCODING_ERROR");
        return new Outcome("FRAME_ENCODING_ERROR", null);
    }
}

private void close(int event, int index, int offset, String code) {
    if (closed) {
        return;
    }
    closed = true;
    closedRow = Main.object("event", (long) event, "packet", (long) index, "offset", (long) offset, "code", code);
}

